# BFCL prescreen for EvoGM v2 (2026-11-15): 160 candidate BFCL non-live items x {Qwen3.5-4B, Baphomet-1.0, Baphomet-1.1},
# n=2 samples each, same sampling as EvoGM fitness (thinking, temp .6 top_p .95 top_k 20 seed 0, max_tokens 4096, fp16 eager, vLLM 0.33.0).
# GPU0: base then 1.0, GPU1: 1.1. Raw outputs -> /kaggle/working/pre_<model>.jsonl (scored offline).
import os, sys, json, time, base64, subprocess
W="/kaggle/working"; T0=time.time()
def log(*a):
    s=time.strftime("%H:%M:%S")+f" [{(time.time()-T0)/60:.1f}m] "+" ".join(map(str,a)); print(s,flush=True); open(f"{W}/progress.log","a").write(s+"\n")
open("/tmp/items.json","wb").write(base64.b64decode(""))
WORKER=r"""
import sys, json, time
from vllm import LLM, SamplingParams
from transformers import AutoTokenizer
def main():
    gpu, jobs = sys.argv[1], sys.argv[2].split(",")
    items=json.load(open("/tmp/items.json"))
    tok=AutoTokenizer.from_pretrained("Qwen/Qwen3.5-4B")
    prompts=[]
    for it in items:
        kw=dict(tokenize=False, add_generation_prompt=True, enable_thinking=True, tools=it["tools"])
        prompts.append(tok.apply_chat_template(it["messages"], **kw))
    REPO={"qwen35":"Qwen/Qwen3.5-4B","baph10":"CloudGoat/Baphomet-1.0-4B","baph11":"CloudGoat/Baphomet-1.1-4B"}
    for j in jobs:
        t=time.time()
        llm=LLM(REPO[j], tokenizer="Qwen/Qwen3.5-4B", dtype="float16", max_model_len=12288, gpu_memory_utilization=0.85, enforce_eager=True,
                enable_prefix_caching=False, seed=0, max_num_seqs=48, limit_mm_per_prompt={"image":0,"video":0})
        sp=SamplingParams(n=2, temperature=0.6, top_p=0.95, top_k=20, seed=0, max_tokens=4096, skip_special_tokens=False)
        outs=llm.generate(prompts, sp)
        with open(f"/kaggle/working/pre_{j}.jsonl","w") as f:
            for it,o in zip(items,outs):
                for s,c in enumerate(o.outputs):
                    f.write(json.dumps(dict(id=it["id"], sample=s, model=j, completion_tokens=len(c.token_ids), finish_reason=c.finish_reason, output=c.text))+"\n")
        print("DONE", j, round(time.time()-t), flush=True)
        del llm
        import gc, torch; gc.collect(); torch.cuda.empty_cache()
        try:
            from vllm.distributed.parallel_state import destroy_model_parallel; destroy_model_parallel()
        except Exception: pass
if __name__ == "__main__":
    main()
"""
open("/tmp/worker.py","w").write(WORKER)
log("pip vllm"); r=subprocess.run(f"pip install --no-cache-dir vllm==0.33.0 > {W}/pip.log 2>&1", shell=True); log("pip rc", r.returncode)
ps=[subprocess.Popen(" ; ".join(f"CUDA_VISIBLE_DEVICES={g} python /tmp/worker.py {g} {j} > {W}/worker_{g}_{j}.log 2>&1" for j in js), shell=True) for g,js in [(0,["qwen35","baph10"]),(1,["baph11"])]]
for p in ps: p.wait()
log("workers rc", [p.returncode for p in ps]); subprocess.run(f"tail -5 {W}/worker_*.log; ls -la {W}", shell=True)
